$twig->addFunction(new \Twig\TwigFunction('__', function($key = null, $file = null, ...$args) {
    if(function_exists('__')) {
        return __($key, $file, ...$args);
    }
    return null;
}));
$twig->addFunction(new \Twig\TwigFunction('route', function($file, $key = []) {
    if(function_exists('route')) {
        return route($file, $key);
    }
    return null;
}));
$twig->addFunction(new \Twig\TwigFunction('controller', function($file, $args) {
    if(function_exists('controller')) {
        if ($args) {
            return registry()->get('load')->controller($file, $args);
        } else {
            return registry()->get('load')->controller($file);
        }
    }
    return null;
}));

// Инициализация GDT Framework и загрузка хуков из admin/controller/hook/
try {
    $this->load->library('gbitstudio/gdt/app');
    if ($this->registry->has('app')) {
        $this->registry->set('gdt', $this->app);
    }
    $this->gdt->init($this->registry);
    $this->load->helper('gdt_helper');
} catch (Exception $e) {
    // Логируем ошибку, но не прерываем выполнение
    error_log('GDT Framework Admin init error: ' . $e->getMessage());
}

